Map<String, String>? _indice;

/// Fabricante de una MAC («AA-BB-CC-…» o «aa:bb:cc:…»), o null si no es de una marca conocida.
String? vantarisFabricanteMac(String mac) {
  final hex = mac.replaceAll(RegExp(r'[^0-9A-Fa-f]'), '').toUpperCase();
  if (hex.length < 6) return null;
  _indice ??= {
    for (final e in _kOui.entries)
      for (final p in e.value.split(' ')) p: e.key,
  };
  return _indice![hex.substring(0, 6)];
}
